    local TEXT1 = "Ban wave is currently happening.. we do not want to be the cause of your ban if not already too late."
    local TEXT2 = "It might be already too late for you as you executed the hub. But close the script for your own good RIGHT NOW and uninstall your executor. Same goes for future ban waves, be informed next time, join our server to know when it would be over"
    local CHAR_DELAY = 0.045
    local PAUSE_AFTER = 1.5

    local function typewrite(label, text, charDelay)
        label.Text = ""
        for i = 1, #text do
            label.Text = string.sub(text, 1, i)
            task.wait(charDelay)
        end
    end

    task.spawn(function()
        WarningLabel_26.Visible = true
        typewrite(WarningLabel_26, TEXT1, CHAR_DELAY)

        task.wait(PAUSE_AFTER)

        WarningLabel_26.Visible = false
        Warning2Label_30.Visible = true
        typewrite(Warning2Label_30, TEXT2, CHAR_DELAY)

        task.wait(PAUSE_AFTER)

        CLOSEnowButton_15.Visible = true
        CLOSEnowButton_15.Active = true
        ContinueButton.Visible = true
